use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_rank(i: Importance) -> u8 {
    match i {
        Importance::MustRead => 0,
        Importance::WorthALook => 1,
        Importance::Skip => 2,
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "Must read",
        Importance::WorthALook => "Worth a look",
        Importance::Skip => "Skip",
    }
}

/// Collapse whitespace and newlines so that adversarial feed text cannot
/// forge structure in the notification body, and bound its length.
fn clean(s: &str, max_chars: usize) -> String {
    let mut out = String::new();
    let mut last_space = false;
    let mut count = 0usize;
    for ch in s.chars() {
        if count >= max_chars {
            out.push('…');
            break;
        }
        if ch.is_whitespace() || ch.is_control() {
            if !last_space && !out.is_empty() {
                out.push(' ');
                count += 1;
                last_space = true;
            }
        } else {
            out.push(ch);
            count += 1;
            last_space = false;
        }
    }
    out.trim_end().to_string()
}

fn render(d: &crate::Digest) -> String {
    let mut msg = String::new();
    msg.push_str("Digest for ");
    msg.push_str(&clean(&d.date, 64));
    msg.push('\n');

    let overview = clean(&d.overview, 2000);
    if !overview.is_empty() {
        msg.push('\n');
        msg.push_str(&overview);
        msg.push('\n');
    }

    let mut entries: Vec<&ItemVerdict> = d.entries.iter().filter(|e| e.kept).collect();
    entries.sort_by_key(|e| importance_rank(e.importance));

    if entries.is_empty() {
        msg.push_str("\nNo items made the digest today.\n");
    } else {
        let mut current: Option<u8> = None;
        for e in entries {
            let rank = importance_rank(e.importance);
            if current != Some(rank) {
                current = Some(rank);
                msg.push('\n');
                msg.push_str("== ");
                msg.push_str(importance_label(e.importance));
                msg.push_str(" ==\n");
            }
            msg.push_str("- [");
            msg.push_str(category_label(e.category));
            msg.push_str("] ");
            msg.push_str(&clean(&e.title, 200));
            let feed = clean(&e.feed, 120);
            if !feed.is_empty() {
                msg.push_str(" (");
                msg.push_str(&feed);
                msg.push(')');
            }
            msg.push('\n');
            let link = clean(&e.link, 500);
            if !link.is_empty() {
                msg.push_str("  ");
                msg.push_str(&link);
                msg.push('\n');
            }
            let summary = clean(&e.summary, 600);
            if !summary.is_empty() {
                msg.push_str("  ");
                msg.push_str(&summary);
                msg.push('\n');
            }
        }
    }

    msg.push_str("\n(");
    msg.push_str(&d.considered.len().to_string());
    msg.push_str(" items considered)\n");
    msg
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        let published = notifier::notify(&message);
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
